/**
 * Unit tests for CategoryPlot.getRangeAxisIndex
 */
public class CategoryPlot_getRangeAxisIndex_TriageGen0Test {

    private CategoryPlot categoryPlot;
    private ValueAxis mockAxis;

    @Before
    public void setUp() {
        categoryPlot = new CategoryPlot();
        mockAxis = mock(ValueAxis.class);
    }

    /**
     * Test case where the axis is found directly in the CategoryPlot's range axes.
     */
    @Test
    public void testGetRangeAxisIndex_FoundInCurrentPlot() throws Exception {
        // We need to populate the rangeAxes list. 
        // Since rangeAxes is likely private, we use reflection or the public setter.
        ValueAxis axis1 = mock(ValueAxis.class);
        ValueAxis axis2 = mock(ValueAxis.class);

        categoryPlot.setRangeAxes(new ValueAxis[]{axis1, axis2});

        int index = categoryPlot.getRangeAxisIndex(axis2);
        assertEquals("Should return index 1 when axis is at index 1", 1, index);
    }

    /**
     * Test case where the axis is NOT in the current CategoryPlot, 
     * but is found in the parent Plot (which is also a CategoryPlot).
     */
    @Test
    public void testGetRangeAxisIndex_FoundInParentPlot() throws Exception {
        // Setup Parent CategoryPlot
        CategoryPlot parentPlot = new CategoryPlot();
        ValueAxis parentAxis = mock(ValueAxis.class);
        parentPlot.setRangeAxes(new ValueAxis[]{parentAxis});

        // Setup Child CategoryPlot
        CategoryPlot childPlot = new CategoryPlot();
        // We must link childPlot to parentPlot. 
        // In JFreeChart, Plot.setParent is usually used.
        setPrivateField(childPlot, "parent", parentPlot);

        // The axis is not in child, but is in parent
        int index = childPlot.getRangeAxisIndex(parentAxis);
        assertEquals("Should return index 0 from the parent CategoryPlot", 0, index);
    }

    /**
     * Test case where the axis is not found in the current plot and not found in the parent plot.
     */
    @Test
    public void testGetRangeAxisIndex_NotFoundInCurrentOrParent() throws Exception {
        // Setup Parent Plot
        CategoryPlot parentPlot = new CategoryPlot();
        parentPlot.setRangeAxes(new ValueAxis[]{mock(ValueAxis.class)});

        // Setup Child Plot
        CategoryPlot childPlot = new CategoryPlot();
        setPrivateField(childPlot, "parent", parentPlot);

        // Axis is totally new
        int index = childPlot.getRangeAxisIndex(mockAxis);
        assertEquals("Should return -1 if axis is nowhere to be found", -1, index);
    }

    /**
     * Test case where the axis is not found in the current plot, 
     * and the parent exists but is NOT a CategoryPlot.
     */
    @Test
    public void testGetRangeAxisIndex_ParentIsNotCategoryPlot() throws Exception {
        // Mock a generic Plot that is not a CategoryPlot
        Plot genericPlot = mock(Plot.class);

        CategoryPlot childPlot = new CategoryPlot();
        setPrivateField(childPlot, "parent", genericPlot);

        int index = childPlot.getRangeAxisIndex(mockAxis);
        assertEquals("Should return -1 if parent is not a CategoryPlot", -1, index);
    }

    /**
     * Helper method to set private fields for testing purposes (to simulate hierarchy).
     */
    private void setPrivateField(Object object, String fieldName, Object value) throws Exception {
        Field field = object.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(object, value);
    }
}
